<body>
  <main id="app"></main>
  <script type="module">
    const app = document.querySelector('#app');
    const escapeHtml = (value) => String(value).replace(/[&<>"']/g, (char) => ({
      '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
    })[char]);

    async function showProjects() {
      const projects = await fetch('/api/projects').then((response) => response.json());
      app.innerHTML = `
        <h1>Workboard</h1>
        <form id="create-project">
          <label for="project-name">Project name<input id="project-name" name="name" type="text" autocomplete="off"></label>
          <button type="submit">Create project</button>
        </form>
        <p id="error" role="alert" hidden></p>
        <section id="projects" aria-label="Projects">${projects.map((project) => `
          <div class="project-row" data-testid="project-row">
            <span class="project-name">${escapeHtml(project.name)}</span>
            <button type="button" data-project-id="${project.id}">Open project</button>
          </div>`).join('')}</section>`;
      app.querySelector('#create-project').addEventListener('submit', async (event) => {
        event.preventDefault();
        const name = app.querySelector('#project-name').value.trim();
        if (!name) {
          const error = app.querySelector('#error');
          error.textContent = 'Project name is required';
          error.hidden = false;
          return;
        }
        const response = await fetch('/api/projects', {
          method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ name })
        });
        if (response.ok) showProjects();
      });
      app.querySelectorAll('[data-project-id]').forEach((button) => button.addEventListener('click', () => {
        window.history.pushState({}, '', `/projects/${button.dataset.projectId}`);
        showProject(button.dataset.projectId);
      }));
    }

    async function showProject(id) {
      const response = await fetch(`/api/projects/${encodeURIComponent(id)}`);
      if (!response.ok) { window.history.replaceState({}, '', '/'); return showProjects(); }
      const project = await response.json();
      app.innerHTML = `<button type="button" id="back">Projects</button><h1>${escapeHtml(project.name)}</h1>
        <form id="create-task"><label for="task-title">Task title<input id="task-title" name="title" type="text" autocomplete="off"></label><button type="submit">Create task</button></form>
        <p id="task-error" role="alert" hidden></p>
        <label for="task-filter">Task filter<select id="task-filter"><option>All</option><option>Open</option><option>Completed</option></select></label>
        <section id="tasks" aria-label="Tasks"></section>`;
      app.querySelector('#back').addEventListener('click', () => {
        window.history.pushState({}, '', '/');
        showProjects();
      });
      const taskUrl = `/api/projects/${encodeURIComponent(id)}/tasks`;
      const filter = app.querySelector('#task-filter');
      async function renderTasks() {
        const tasks = await fetch(taskUrl).then((result) => result.json());
        const selected = filter.value;
        const visible = tasks.filter((task) => selected === 'All' || (selected === 'Open' && !task.completed) || (selected === 'Completed' && task.completed));
        app.querySelector('#tasks').innerHTML = visible.map((task) => `<div class="task-row" data-testid="task-row"><input type="checkbox" data-task-id="${task.id}" aria-label="Complete ${escapeHtml(task.title)}" ${task.completed ? 'checked' : ''}><span>${escapeHtml(task.title)}</span></div>`).join('');
        app.querySelectorAll('[data-task-id]').forEach((checkbox) => checkbox.addEventListener('change', async () => {
          await fetch(`${taskUrl}/${checkbox.dataset.taskId}`, { method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ completed: checkbox.checked }) });
          renderTasks();
        }));
      }
      filter.addEventListener('change', renderTasks);
      app.querySelector('#create-task').addEventListener('submit', async (event) => {
        event.preventDefault();
        const title = app.querySelector('#task-title').value.trim();
        const error = app.querySelector('#task-error');
        if (!title) { error.textContent = 'Task title is required'; error.hidden = false; return; }
        const result = await fetch(taskUrl, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ title }) });
        if (result.ok) { error.hidden = true; app.querySelector('#task-title').value = ''; renderTasks(); }
      });
      renderTasks();
    }

    function renderRoute() {
      const match = window.location.pathname.match(/^\/projects\/([^/]+)\/?$/);
      if (match) showProject(decodeURIComponent(match[1])); else showProjects();
    }
    window.addEventListener('popstate', renderRoute);
    renderRoute();
  </script>
</body>
</html>

